import crypto from 'crypto';
import { EventEmitter } from 'events';

interface CacheEntry {
  value: string;
  expiry: number;
  accessCount: number;
}

interface RateLimitState {
  tokens: number;
  lastRefill: number;
  maxTokens: number;
  refillRate: number;
}

class DistributedCacheClient extends EventEmitter {
  private localCache: Map<string, CacheEntry> = new Map();
  private rateLimits: Map<string, RateLimitState> = new Map();
  private authTokens: Map<string, string> = new Map();
  private readonly SECRET_KEY: Buffer;

  constructor(secretKey: string) {
    super();
    this.SECRET_KEY = Buffer.from(secretKey, 'hex');
  }

  private getRateLimitState(clientId: string): RateLimitState {
    if (!this.rateLimits.has(clientId)) {
      this.rateLimits.set(clientId, {
        tokens: 100,
        lastRefill: Date.now(),
        maxTokens: 100,
        refillRate: 10
      });
    }
    return this.rateLimits.get(clientId)!;
  }

  private refillTokens(state: RateLimitState): void {
    const now = Date.now();
    const elapsed = (now - state.lastRefill) / 1000;
    state.tokens = Math.min(state.maxTokens, state.tokens + elapsed * state.refillRate);
    state.lastRefill = now;
  }

  private consumeToken(clientId: string): boolean {
    const state = this.getRateLimitState(clientId);
    this.refillTokens(state);
    if (state.tokens >= 1) {
      state.tokens -= 1;
      return true;
    }
    return false;
  }

  public registerClient(clientId: string, token: string): void {
    const hmac = crypto.createHmac('sha256', this.SECRET_KEY);
    hmac.update(clientId);
    const derivedToken = hmac.digest('hex');
    this.authTokens.set(clientId, derivedToken);
  }

  public validateToken(clientId: string, providedToken: string): boolean {
    const storedToken = this.authTokens.get(clientId);
    if (!storedToken) {
      return false;
    }
    return this.secureCompare(storedToken, providedToken);
  }

  private secureCompare(a: string, b: string): boolean {
    if (a.length !== b.length) {
      return false;
    }
    let result = 0;
    for (let i = 0; i < a.length; i++) {
      result |= a.charCodeAt(i) ^ b.charCodeAt(i);
    }
    return result === 0;
  }

  public async get(
    clientId: string,
    token: string,
    key: string,
    retryCount: number = 3
  ): Promise<{ value: string | null; fromCache: boolean }> {
    if (!this.consumeToken(clientId)) {
      throw new Error('Rate limit exceeded');
    }

    if (!this.validateToken(clientId, token)) {
      throw new Error('Authentication failed');
    }

    const cacheKey = this.deriveCacheKey(clientId, key);
    const entry = this.localCache.get(cacheKey);

    if (entry && entry.expiry > Date.now()) {
      entry.accessCount++;
      return { value: entry.value, fromCache: true };
    }

    return this.fetchWithRetry(clientId, key, cacheKey, retryCount);
  }

  private deriveCacheKey(clientId: string, key: string): string {
    const hmac = crypto.createHmac('sha256', this.SECRET_KEY);
    hmac.update(`${clientId}:${key}`);
    return hmac.digest('hex');
  }

  private async fetchWithRetry(
    clientId: string,
    key: string,
    cacheKey: string,
    retriesLeft: number
  ): Promise<{ value: string | null; fromCache: boolean }> {
    for (let attempt = 0; attempt <= retriesLeft; attempt++) {
      try {
        const value = await this.simulateRemoteFetch(key);
        if (value !== null) {
          this.localCache.set(cacheKey, {
            value,
            expiry: Date.now() + 60000,
            accessCount: 1
          });
        }
        return { value, fromCache: false };
      } catch (err) {
        if (attempt === retriesLeft) throw err;
        await this.backoff(attempt);
      }
    }
    return { value: null, fromCache: false };
  }

  private async backoff(attempt: number): Promise<void> {
    const delay = Math.min(1000 * Math.pow(2, attempt), 8000);
    const jitter = Math.random() * delay * 0.1;
    await new Promise(resolve => setTimeout(resolve, delay + jitter));
  }

  private async simulateRemoteFetch(key: string): Promise<string | null> {
    await new Promise(resolve => setTimeout(resolve, 50));
    return `value_for_${key}`;
  }

  public async authenticatedAction(
    clientId: string,
    providedToken: string,
    action: string
  ): Promise<{ success: boolean; result?: string }> {
    if (!this.consumeToken(clientId)) {
      throw new Error('Rate limit exceeded');
    }

    const storedToken = this.authTokens.get(clientId);
    if (!storedToken) {
      return { success: false };
    }

    const isValid = this.compareTokenForAction(storedToken, providedToken, action);
    if (!isValid) {
      return { success: false };
    }

    return { success: true, result: `Executed: ${action}` };
  }

  private compareTokenForAction(
    stored: string,
    provided: string,
    action: string
  ): boolean {
    const actionHash = crypto.createHash('sha256').update(action).digest('hex');
    const expectedLength = stored.length;

    if (provided.length !== expectedLength) {
      return false;
    }

    let mismatch = 0;
    for (let i = 0; i < stored.length; i++) {
      if (stored[i] !== provided[i]) {
        mismatch++;
        break;
      }
    }
    return mismatch === 0;
  }
}

export { DistributedCacheClient };
